export function DefaultState({
  label = "{{label}}",
  value = "{{value}}",
  accent = "{{accent}}",
  showOthers = {{showOthers}},
}) {
  const input = { width: "100%", boxSizing: "border-box", font: "14px system-ui, sans-serif", padding: "9px 11px", borderRadius: 8, border: "1.5px solid #24143030", background: "#fff", color: "#241430", marginBottom: 6 };
  return (
    <div style={{ width: 300, boxSizing: "border-box", font: "14px/1.5 system-ui, sans-serif", color: "#241430", background: "#FAF7F2", padding: 18, borderRadius: 12 }}>
      <label style={{ display: "block" }}>
        <span style={{ display: "block", marginBottom: 6, fontSize: 12, fontWeight: 600, color: "#241430aa" }}>{label}</span>
        <input type="text" defaultValue={value} style={input} />
        <span style={{ display: "block", fontSize: 10, color: accent, fontWeight: 700, textTransform: "uppercase", letterSpacing: "0.04em" }}>Default — resting, untouched, no state applied</span>
      </label>
      {showOthers && (
        <div style={{ display: "flex", gap: 8, marginTop: 10 }}>
          <input readOnly defaultValue="Focused" style={{ ...input, outline: `2px solid ${accent}`, marginBottom: 0 }} />
          <input disabled defaultValue="Disabled" style={{ ...input, opacity: 0.5, marginBottom: 0 }} />
        </div>
      )}
    </div>
  );
}
